class Sensor
    private define temperature as integer;

    method constructor(aTemperature as integer)
        this.temperature <- aTemperature;
    endMethod

    public method Temperature() as integer
        return this.temperature;
    endMethod
endClass

class Thermostat
    private define sensor as Sensor;

    method constructor(aTemperature as integer)
        this.sensor <- new Sensor(aTemperature);
    endMethod

    public method IsHot() as integer
        if this.sensor.Temperature() > 25 then
            return 1;
        else
            return 0;
        endIf
    endMethod
endClass

algorithm TryThermostat
    define temperature as integer;
    define thermostat as Thermostat;
    read temperature;
    thermostat <- new Thermostat(temperature);
    write thermostat.IsHot();
endAlgorithm
